"""Mantle-only end-to-end assertions.

``_get_all_assertion_subclasses`` imports this module on first lookup so the
subclasses register. Do not import this module from the top of assertions.py.
"""

from __future__ import annotations

import dataclasses
import json
from dataclasses import dataclass
from typing import Any, ClassVar, Dict, List, Optional, Self, Set, Text, Tuple

from rasa.e2e_test.assertions import (
    AssertedSlot,
    Assertion,
    AssertionFailure,
    AssertionType,
    InvalidAssertionType,
    _get_turn_events_based_on_step_index,
)
from rasa.shared.core.events import (
    Event,
    MemoryCleared,
    MemorySet,
    OrderedBlockCancelled,
    OrderedBlockCompleted,
    OrderedBlockEntered,
    OrderedBlockInterrupted,
    OrderedBlockResumed,
    SkillActivated,
    SkillCancelled,
    SkillCompleted,
    SkillInterrupted,
    SkillResumed,
    ToolExecuted,
)

_OMITTED_MEMORY_VALUE = "value key is undefined"


def _first_matching_event(turn_events: List[Event], predicate: Any) -> Optional[Event]:
    return next((event for event in turn_events if predicate(event)), None)


def _assertion_line(assertion_dict: Dict[Text, Any]) -> Optional[int]:
    return assertion_dict.lc.line + 1 if hasattr(assertion_dict, "lc") else None


def _reject_null_memory_value(item: Dict[Text, Any], key: str) -> None:
    if "value" in item and item["value"] is None:
        raise InvalidAssertionType(
            f"'{key}' must not use value: null; omit value or use memory_was_cleared"
        )


def _assertion_mapping(
    assertion_dict: Dict[Text, Any], assertion_type: AssertionType
) -> Dict[Text, Any]:
    body = assertion_dict.get(assertion_type.value)
    if not isinstance(body, dict):
        raise InvalidAssertionType(f"{assertion_type.value} requires an object payload")
    return body


def _assertion_sequence(
    assertion_dict: Dict[Text, Any], assertion_type: AssertionType
) -> List[Dict[Text, Any]]:
    body = assertion_dict.get(assertion_type.value)
    if not isinstance(body, list) or not body:
        raise InvalidAssertionType(f"{assertion_type.value} requires a non-empty list")
    return body


def _memory_slots(
    assertion_dict: Dict[Text, Any], assertion_type: AssertionType
) -> List["AssertedSlot"]:
    slots = []
    for item in _assertion_sequence(assertion_dict, assertion_type):
        if assertion_type is AssertionType.MEMORY_WAS_CLEARED:
            if "value" in item:
                raise InvalidAssertionType("memory_was_cleared forbids value")
        else:
            _reject_null_memory_value(item, assertion_type.value)
        slots.append(AssertedSlot.from_dict(item))
    return slots


def _fail_missing(
    assertion: "Assertion",
    message: str,
    prior_events: List[Event],
    turn_events: List[Event],
    assertion_order_error_message: str,
    line: Optional[int],
) -> Tuple[AssertionFailure, None]:
    return assertion.generate_test_failure(
        message,
        assertion_order_error_message,
        prior_events,
        turn_events,
        line,
    )


def _hashable_assertion(cls: type) -> type:
    """Restore ``__hash__``; ``@dataclass`` sets it to ``None`` on each subclass."""

    def __hash__(self: Assertion) -> int:
        return hash(json.dumps(self.as_dict()))

    cls.__hash__ = __hash__  # type: ignore[assignment]
    return cls


class _TrackedIdAssertion:
    """Shared parse/match for skill and ordered-block assertions.

    Not an ``Assertion`` subclass, so it is not auto-registered.
    """

    assertion_type: ClassVar[AssertionType]
    event_type: ClassVar[type]
    required: ClassVar[tuple]
    noun: ClassVar[str]
    past: ClassVar[str]
    label_field: ClassVar[str]
    forbid_step: ClassVar[bool] = False

    @classmethod
    def type(cls) -> str:
        return cls.assertion_type.value

    @classmethod
    def from_dict(cls, assertion_dict: Dict[Text, Any]) -> Self:
        body = _assertion_mapping(assertion_dict, cls.assertion_type)
        missing = [name for name in cls.required if not body.get(name)]
        if missing or (cls.forbid_step and "step_id" in body):
            needed = " and ".join(cls.required)
            extra = " and forbids step_id" if cls.forbid_step else ""
            raise InvalidAssertionType(
                f"{cls.assertion_type.value} requires {needed}{extra}"
            )
        values: Dict[str, Any] = {name: body[name] for name in cls.required}
        if dataclasses.is_dataclass(cls) and any(
            field.name == "step_id" for field in dataclasses.fields(cls)
        ):
            values["step_id"] = body.get("step_id")
        values["line"] = _assertion_line(assertion_dict)
        return cls(**values)

    def _event_matches(self, event: Event) -> bool:
        if not isinstance(event, type(self).event_type):
            return False
        if any(
            getattr(event, name) != getattr(self, name) for name in type(self).required
        ):
            return False
        step_id = getattr(self, "step_id", None)
        return step_id is None or getattr(event, "step_id", None) == step_id

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        matching = _first_matching_event(turn_events, self._event_matches)
        if matching is None:
            ident = getattr(self, type(self).label_field)
            return _fail_missing(
                self,
                f"{type(self).noun} '{ident}' was not {type(self).past}.",
                prior_events,
                turn_events,
                assertion_order_error_message,
                getattr(self, "line", None),
            )
        return None, matching


