@_hashable_assertion
@dataclass
class MemoryWasSetAssertion(Assertion):
    """Assert memory keys were written."""

    slots: List[AssertedSlot]
    line: Optional[int] = None

    @classmethod
    def type(cls) -> str:
        return AssertionType.MEMORY_WAS_SET.value

    @staticmethod
    def from_dict(assertion_dict: Dict[Text, Any]) -> "MemoryWasSetAssertion":
        return MemoryWasSetAssertion(
            slots=_memory_slots(assertion_dict, AssertionType.MEMORY_WAS_SET),
            line=_assertion_line(assertion_dict),
        )

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        """Run the memory_was_set assertion."""
        matching_event: Optional[Event] = None
        original_turn_events, scoped = _get_turn_events_based_on_step_index(
            kwargs.get("step_index"), turn_events, prior_events
        )
        for slot in self.slots:
            matching_events = [
                event
                for event in scoped
                if isinstance(event, MemorySet) and event.key == slot.name
            ]
            if not matching_events:
                return _fail_missing(
                    self,
                    f"Memory '{slot.name}' was not set.",
                    prior_events,
                    original_turn_events,
                    assertion_order_error_message,
                    slot.line,
                )
            if slot.value == _OMITTED_MEMORY_VALUE:
                matching_event = matching_events[0]
                continue
            try:
                matching_event = next(
                    event for event in matching_events if event.value == slot.value
                )
            except StopIteration:
                return _fail_missing(
                    self,
                    f"Memory '{slot.name}' was set to a different value.",
                    prior_events,
                    original_turn_events,
                    assertion_order_error_message,
                    slot.line,
                )
        return None, matching_event


@_hashable_assertion
@dataclass
class MemoryWasNotSetAssertion(Assertion):
    """Assert memory keys were not written."""

    slots: List[AssertedSlot]
    line: Optional[int] = None

    @classmethod
    def type(cls) -> str:
        return AssertionType.MEMORY_WAS_NOT_SET.value

    @staticmethod
    def from_dict(assertion_dict: Dict[Text, Any]) -> "MemoryWasNotSetAssertion":
        return MemoryWasNotSetAssertion(
            slots=_memory_slots(assertion_dict, AssertionType.MEMORY_WAS_NOT_SET),
            line=_assertion_line(assertion_dict),
        )

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        """Run the memory_was_not_set assertion."""
        matching_event: Optional[Event] = None
        original_turn_events, scoped = _get_turn_events_based_on_step_index(
            kwargs.get("step_index"), turn_events, prior_events
        )
        for slot in self.slots:
            matching_events = [
                event
                for event in scoped
                if isinstance(event, MemorySet) and event.key == slot.name
            ]
            if not matching_events:
                continue
            matching_event = matching_events[-1]
            if slot.value == _OMITTED_MEMORY_VALUE:
                return _fail_missing(
                    self,
                    f"Memory '{slot.name}' was set.",
                    prior_events,
                    original_turn_events,
                    assertion_order_error_message,
                    slot.line,
                )
            if matching_event.value == slot.value:
                return _fail_missing(
                    self,
                    f"Memory '{slot.name}' was set to '{slot.value}'.",
                    prior_events,
                    original_turn_events,
                    assertion_order_error_message,
                    slot.line,
                )
        return None, matching_event


@_hashable_assertion
@dataclass
class MemoryWasClearedAssertion(Assertion):
    """Assert memory keys were cleared."""

    slots: List[AssertedSlot]
    line: Optional[int] = None

    @classmethod
    def type(cls) -> str:
        return AssertionType.MEMORY_WAS_CLEARED.value

    @staticmethod
    def from_dict(assertion_dict: Dict[Text, Any]) -> "MemoryWasClearedAssertion":
        return MemoryWasClearedAssertion(
            slots=_memory_slots(assertion_dict, AssertionType.MEMORY_WAS_CLEARED),
            line=_assertion_line(assertion_dict),
        )

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        """Run the memory_was_cleared assertion."""
        matching_event: Optional[Event] = None
        original_turn_events, scoped = _get_turn_events_based_on_step_index(
            kwargs.get("step_index"), turn_events, prior_events
        )
        for slot in self.slots:
            matching = _first_matching_event(
                scoped,
                lambda event, name=slot.name: (
                    isinstance(event, MemoryCleared) and event.key == name
                ),
            )
            if matching is None:
                return _fail_missing(
                    self,
                    f"Memory '{slot.name}' was not cleared.",
                    prior_events,
                    original_turn_events,
                    assertion_order_error_message,
                    slot.line,
                )
            matching_event = matching
        return None, matching_event


