def tool_executed_event_matches(
    assertion: "ToolExecutedAssertion", event: Event
) -> bool:
    """Return whether ``event`` satisfies a ``tool_executed`` assertion."""
    if not isinstance(event, ToolExecuted):
        return False
    if event.tool_name != assertion.tool_name or event.source != assertion.source:
        return False
    if assertion.source == "mcp" and event.mcp_server != assertion.mcp_server:
        return False
    if assertion.skill_id is not None:
        metadata = event.metadata if isinstance(event.metadata, dict) else {}
        if metadata.get("skill_id") != assertion.skill_id:
            return False
    if assertion.arguments:
        observed = event.arguments or {}
        if any(
            observed.get(key) != value for key, value in assertion.arguments.items()
        ):
            return False
    if assertion.is_error is not None and event.is_error != assertion.is_error:
        return False
    return True


@_hashable_assertion
@dataclass
class ToolExecutedAssertion(Assertion):
    """Assert one tool run."""

    tool_name: str
    source: str
    mcp_server: Optional[str] = None
    skill_id: Optional[str] = None
    arguments: Optional[Dict[str, Any]] = None
    is_error: Optional[bool] = None
    line: Optional[int] = None

    @classmethod
    def type(cls) -> str:
        return AssertionType.TOOL_EXECUTED.value

    @staticmethod
    def from_dict(assertion_dict: Dict[Text, Any]) -> "ToolExecutedAssertion":
        body = _assertion_mapping(assertion_dict, AssertionType.TOOL_EXECUTED)
        tool_name, source = body.get("tool_name"), body.get("source")
        if not tool_name or source not in {"local", "mcp"}:
            raise InvalidAssertionType(
                "tool_executed requires tool_name and source local|mcp"
            )
        has_server = "mcp_server" in body
        if source == "mcp" and not has_server:
            raise InvalidAssertionType("mcp_server is required when source is mcp")
        if source == "local" and has_server:
            raise InvalidAssertionType("mcp_server is forbidden when source is local")
        return ToolExecutedAssertion(
            tool_name=tool_name,
            source=source,
            mcp_server=body.get("mcp_server"),
            skill_id=body.get("skill_id"),
            arguments=body.get("arguments"),
            is_error=body.get("is_error"),
            line=_assertion_line(assertion_dict),
        )

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        """Run the tool_executed assertion."""
        matching = _first_matching_event(
            turn_events, lambda event: tool_executed_event_matches(self, event)
        )
        if matching is None:
            return _fail_missing(
                self,
                f"Tool '{self.tool_name}' was not executed.",
                prior_events,
                turn_events,
                assertion_order_error_message,
                self.line,
            )
        return None, matching


def _match_calls(
    calls: List["ToolExecutedAssertion"], events: List[Event], ordered: bool
) -> Tuple[Optional[Event], Optional[Set[int]]]:
    used: Set[int] = set()
    last: Optional[Event] = None
    cursor = 0
    for call in calls:
        found = None
        start = cursor if ordered else 0
        for index in range(start, len(events)):
            event = events[index]
            if id(event) in used:
                continue
            if tool_executed_event_matches(call, event):
                found = event
                used.add(id(event))
                if ordered:
                    cursor = index + 1
                break
        if found is None:
            return None, None
        last = found
    return last, used


@_hashable_assertion
@dataclass
class ToolsWithinOneTurnAssertion(Assertion):
    """Assert every listed tool ran inside one user turn.

    Unordered matching is greedy in listed-call order. Each call consumes one
    distinct event. There is no backtracking.
    """

    calls: List[ToolExecutedAssertion]
    allow_extra_calls: bool
    ordered: bool = False
    line: Optional[int] = None

    @classmethod
    def type(cls) -> str:
        return AssertionType.TOOLS_WITHIN_ONE_TURN.value

    @staticmethod
    def from_dict(assertion_dict: Dict[Text, Any]) -> "ToolsWithinOneTurnAssertion":
        body = _assertion_mapping(assertion_dict, AssertionType.TOOLS_WITHIN_ONE_TURN)
        if "same_turn" in body:
            raise InvalidAssertionType(
                "tools_within_one_turn does not accept same_turn"
            )
        calls_raw = body.get("calls")
        if not isinstance(calls_raw, list) or len(calls_raw) < 2:
            raise InvalidAssertionType(
                "tools_within_one_turn.calls must have at least two items"
            )
        calls = []
        for item in calls_raw:
            if not isinstance(item, dict) or list(item) != ["tool_executed"]:
                raise InvalidAssertionType(
                    "each call must be a single tool_executed object"
                )
            calls.append(ToolExecutedAssertion.from_dict(item))
        if "allow_extra_calls" not in body or not isinstance(
            body["allow_extra_calls"], bool
        ):
            raise InvalidAssertionType("allow_extra_calls is required")
        ordered = body.get("ordered", False)
        if not isinstance(ordered, bool):
            raise InvalidAssertionType("ordered must be a boolean")
        return ToolsWithinOneTurnAssertion(
            calls=calls,
            ordered=ordered,
            allow_extra_calls=body["allow_extra_calls"],
            line=_assertion_line(assertion_dict),
        )

    def run(
        self,
        turn_events: List[Event],
        prior_events: List[Event],
        assertion_order_error_message: str = "",
        **kwargs: Any,
    ) -> Tuple[Optional[AssertionFailure], Optional[Event]]:
        """Run the tools_within_one_turn assertion."""
        # event_ledger lives under rasa.builder.copilot, whose package init
        # imports the third-party ``agents`` SDK. Importing it here keeps
        # ``rasa --help`` (script path ``rasa/__main__.py``) from resolving
        # that name to ``rasa/agents``.
        from rasa.builder.copilot.mcp_server.tools.event_ledger import (
            is_user_relevant_tool_run,
            split_into_turns,
        )

        for _turn_idx, turn in split_into_turns(turn_events):
            relevant = [
                event
                for event in turn
                if isinstance(event, ToolExecuted) and is_user_relevant_tool_run(event)
            ]
            last, used = _match_calls(self.calls, relevant, ordered=self.ordered)
            if last is None or used is None:
                continue
            if self.allow_extra_calls is False and len(used) != len(relevant):
                continue
            return None, last
        return _fail_missing(
            self,
            "tools_within_one_turn calls were not all found on one turn.",
            prior_events,
            turn_events,
            assertion_order_error_message,
            self.line,
        )
